//! sattr (*sáttr*, an agreement): the extension API's two hosts (docs/develop/standards/api-versioning.md).
//!
//! The WIT is `crates/ext/mal/drgnx.wit`. Everything that binds a function of it to Luau or to a component is
//! generated by mal-gen (`build.rs`): nothing here binds one by hand, and the `no-hand-luau-binding` scan rule rejects
//! a hand-written userdata impl of mlua anywhere else. [`editor::Editor`] implements the generated `Api` trait once
//! on the standards' crates (bod, lykill, skipan, spurn, tidindi), and both hosts call it.
//!
//! Every call carries a [`Caller`]: which extension, and for whom (the origin that started the chain). The editor
//! decides on it. Both hosts run an extension under the same [`Limits`].
//!
//! - [`generated`]: the traits, the enums, `install_luau`, `WasmApi`, `wasm_link` and the callers of the exports;
//! - [`luau`]: the Luau host, sandboxed, with a step budget and a memory limit;
//! - [`wasm`]: the component host's bindings, store state, engine, fuel, memory limit and epoch ticker;
//! - [`editor`]: the API's implementation.

pub mod editor;
pub mod luau;
pub mod wasm;

/// Who is calling the API: the extension, and the origin of the request it is serving (the user, an agent, or the
/// extension itself): an agent that has an extension act stays the agent.
#[derive(Clone, Debug)]
pub struct Caller {
    pub extension: String,
    pub origin: bod::Origin,
}

/// What one extension may use, in both hosts.
#[derive(Clone, Copy, Debug)]
pub struct Limits {
    /// Luau: interrupt steps a call may take. Components: fuel a call may burn.
    pub steps: u64,
    /// The memory the extension may hold, in bytes.
    pub memory_bytes: usize,
    /// Wall-clock time a call may take, in milliseconds. Luau checks the clock itself; components get it as epoch ticks
    /// (1 ms each, while a [`wasm::ticker`] runs).
    pub ticks: u64,
    /// The largest table a component may grow (elements).
    pub table_elements: usize,
    /// The longest list an extension may hand the API (elements), or be handed back.
    pub max_list: usize,
    /// The resource handles an extension may hold at once, over all resource types (see the `drgnx:api` WIT's
    /// resources): the next one is refused until a handle is dropped.
    pub handles: usize,
}

impl Limits {
    /// What an extension gets unless the user says otherwise.
    pub const DEFAULT: Limits = Limits {
        steps: 5_000_000,
        memory_bytes: 16 << 20,
        ticks: 2_000,
        table_elements: 10_000,
        max_list: 256,
        handles: 4096,
    };
}

/// An extension's name: `a-z`, `0-9` and `-` only, so that the ids made from it (`ext/<name>/<id>`) cannot collide
/// (no `/`, no case, no space).
pub fn valid_extension_name(name: &str) -> villa::Result<()> {
    let ok = !name.is_empty()
        && name.len() <= 64
        && name
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-');
    if ok {
        Ok(())
    } else {
        Err(villa::Error::invalid(
            "An extension's name is lower-case letters, digits and `-`, up to 64.",
        )
        .with_detail(name.to_string()))
    }
}

/// The generated bindings (see build.rs).
// dead_code: the bindings cover the whole API, and a given crate calls only part of it
#[allow(dead_code)]
pub mod generated {
    include!(concat!(env!("OUT_DIR"), "/api_gen.rs"));
}
